<?php
require __DIR__.'/../app/bootstrap.php';$u=user();if(!$u||!allowed('reports',$u)){http_response_code(403);exit('Access denied.');}
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');foreach([$from,$to] as $d){if(!is_string($d)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$d)){http_response_code(422);exit('Invalid date range.');}}
header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="uncorked-reservations.csv"');$out=fopen('php://output','w');fputcsv($out,['Reference','Customer','Occasion','Date','Status','Event total PHP','Recorded payments PHP']);$rows=run('SELECT r.*,(SELECT COALESCE(SUM(amount),0) FROM payments WHERE reservation_id=r.id) AS paid FROM reservations r WHERE date BETWEEN ? AND ? ORDER BY date',[$from,$to])->fetchAll();foreach($rows as $r){$cells=[$r['reference'],$r['name'],$r['event_type'],$r['date'],$r['status'],number_format($r['total']/100,2,'.',''),number_format($r['paid']/100,2,'.','')];$cells=array_map(fn($v)=>preg_match('/^[=+@\-\t\r]/',(string)$v)?"'".$v:$v,$cells);fputcsv($out,$cells);}audit('Exported reservation report');
